from __future__ import annotations

def lift(a: int, b: int, modulus: int) -> tuple[int, int, int]:
    return (a*a % modulus, a*b % modulus, b*b % modulus)

def check_naturality(a: int, b: int, modulus: int) -> None:
    before = tuple(x % modulus for x in (a*a, a*b, b*b))
    after = lift(a % modulus, b % modulus, modulus)
    assert before == after
    print(f"mod {modulus}: {before}")

for m in (2, 5, 7, 11): check_naturality(17, 23, m)

