from __future__ import annotations

def symmetric_square_pipeline(a: int, b: int) -> dict[str, object]:
    parameters = (a*a, a*b, b*b)
    return {
        "parameters": parameters,
        "trace": sum(parameters),
        "central_character": parameters[0]*parameters[1]*parameters[2],
        "expected_central_character": (a*b)**3,
    }

from __future__ import annotations
from typing import Sequence

def convolve(p: Sequence[int], q: Sequence[int]) -> list[int]:
    out = [0] * (len(p)+len(q)-1)
    for i, x in enumerate(p):
        for j, y in enumerate(q): out[i+j] += x*y
    return out

def verify_factorization(a: int, b: int) -> bool:
    def euler(xs: Sequence[int]) -> list[int]:
        p = [1]
        for x in xs: p = convolve(p, [1, -x])
        return p
    tensor = euler((a*a, a*b, a*b, b*b))
    factors = convolve(euler((a*a, a*b, b*b)), euler((a*b,)))
    return tensor == factors

